export type PolicySection = {
  heading: string;
  paragraphs: string[];
};

export type PolicyDraft = {
  slug: string;
  title: string;
  summary: string;
  status: string;
  owner: string;
  sections: PolicySection[];
};

// 這些內容是產品可見的草稿骨架，不代表法務、客服或 release owner 已核准。
export const policyDrafts: Record<string, PolicyDraft> = {
  terms: {
    slug: "terms",
    title: "使用條款（草稿）",
    summary: "說明 CelebrateDeal 平台、帳號、內容、方案與服務變更的基本邊界。",
    status: "DRAFT — HUMAN LEGAL REVIEW REQUIRED",
    owner: "privacy／legal owner、release owner",
    sections: [
      {
        heading: "服務與帳號責任",
        paragraphs: [
          "正式條款需要由產品與法務 owner 確認服務範圍、商家責任、帳號安全、授權成員與停用條件。",
          "目前產品只提供登入、角色、MFA 與商家營運功能；本頁不取代正式合約或個別商家約定。",
        ],
      },
      {
        heading: "方案、付款與內容",
        paragraphs: [
          "方案、付款、退款、內容使用權與第三方服務的正式文字尚待核准，不能以本機或 Sandbox 結果推論為正式承諾。",
        ],
      },
      {
        heading: "版本、變更與聯絡",
        paragraphs: [
          "正式版本應標示生效日期、變更摘要、適用環境與申訴／聯絡路徑；目前尚未完成真人 owner acceptance。",
        ],
      },
    ],
  },
  privacy: {
    slug: "privacy",
    title: "隱私與資料請求（草稿）",
    summary: "整理資料用途、保存、第三方服務與資料請求流程的待核准入口。",
    status: "DRAFT — HUMAN PRIVACY REVIEW REQUIRED",
    owner: "privacy／legal owner、平台 owner",
    sections: [
      {
        heading: "資料類型與用途",
        paragraphs: [
          "正式隱私通知需要逐項盤點帳號、商家設定、公開頁互動、付款／退款參照、稽核與安全事件資料，並由 owner 確認每項用途與必要性。",
          "產品與測試 evidence 只保存最小化、去識別或 synthetic 參照；不在此頁顯示憑證、Token、Cookie、完整付款資料或原始 provider payload。",
        ],
      },
      {
        heading: "保存、刪除與資料請求",
        paragraphs: [
          "保存期限、刪除例外、資料匯出、更正與其他請求的正式流程尚待隱私／法務 owner review；在核准前，本頁不承諾特定期限或法定結論。",
        ],
      },
      {
        heading: "第三方服務與事件通知",
        paragraphs: [
          "PayUni、Cloudflare、監控與分析服務的實際啟用範圍、資料流向與事件通知文字，仍需要外部設定 evidence 與真人核准。",
        ],
      },
    ],
  },
  refunds: {
    slug: "refunds",
    title: "退款與付款支援政策（草稿）",
    summary: "讓使用者先看到退款申請、狀態不明與升級處理的產品邊界。",
    status: "DRAFT — FINANCE／SUPPORT／LEGAL REVIEW REQUIRED",
    owner: "finance owner、support owner、privacy／legal owner",
    sections: [
      {
        heading: "申請與狀態判讀",
        paragraphs: [
          "退款應依可追溯的交易／退款參照與核准流程處理；不以客服敘述、截圖或單一通知直接重送退款或改寫帳務狀態。",
          "部分退款、全額退款、重複請求與付款狀態不明的產品狀態可在本機與受控 Sandbox 流程驗證，但不代表正式 provider 或商家政策已核准。",
        ],
      },
      {
        heading: "客服交接與禁止事項",
        paragraphs: [
          "客服不應要求完整卡號、CVV、密碼、Token、Cookie 或原始 provider payload；狀態衝突時應停止自動操作並升級財務／平台 owner。",
          "正式退款資格、時間、例外、付款方式差異與法定權利，尚待 finance／support／legal owner 共同核准。",
        ],
      },
    ],
  },
};

export const publicPolicyLinks = [
  { href: "/policies", label: "政策與協助中心" },
  { href: "/policies/terms", label: "使用條款" },
  { href: "/policies/privacy", label: "隱私通知" },
  { href: "/policies/refunds", label: "退款政策" },
  { href: "/support", label: "客服與付款協助" },
  { href: "/merchant-onboarding", label: "商家使用指南" },
] as const;

/** A display label never grants approval or invents a publication version. */
export function publicPolicyTitle(draft: PolicyDraft) {
  return draft.title.replace(/（草稿）$/u, "");
}

import Link from "next/link";
import type { PolicyDraft } from "@/lib/public-policy-content";
import { publicPolicyLinks, publicPolicyTitle } from "@/lib/public-policy-content";

export function PublicResourceLinks({ compact = false }: { compact?: boolean }) {
  return (
    <nav aria-label="公開資訊" className={compact ? "flex flex-wrap justify-center gap-x-4 gap-y-2 text-xs" : "grid gap-2 sm:grid-cols-2"}>
      {publicPolicyLinks.map((link) => (
        <Link key={link.href} href={link.href} className="font-semibold text-primary hover:underline">
          {link.label}
        </Link>
      ))}
    </nav>
  );
}

export function PublicPolicyShell({ children }: { children: React.ReactNode }) {
  return (
    <main className="min-h-screen bg-background px-4 py-8 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-5xl">
        <header className="mb-8 flex flex-wrap items-center justify-between gap-4">
          <Link href="/policies" className="text-sm font-bold text-slate-950">CelebrateDeal</Link>
          <Link href="/login" className="min-h-11 inline-flex items-center rounded-md border border-border bg-white px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
            返回登入
          </Link>
        </header>
        {children}
        <footer className="mt-12 border-t border-border pt-6">
          <PublicResourceLinks compact />
          <p className="mt-4 text-center text-xs leading-5 text-slate-700">
            正式政策版本與生效日期會在發布後公告，請以各頁顯示的發布狀態為準。
          </p>
        </footer>
      </div>
    </main>
  );
}

export function PolicyDraftNotice({ status, owner }: Pick<PolicyDraft, "status" | "owner">) {
  return (
    <div role="status" className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950">
      <p className="font-bold">{status}</p>
      <p className="mt-1 leading-6">核准責任：{owner}。這個頁面不構成法律意見、正式政策或 release sign-off。</p>
    </div>
  );
}

export function UnpublishedPolicyNotice() {
  return <div role="status" className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950">
    <p className="font-bold">政策尚未正式發布</p>
    <p className="mt-1 leading-6">正式政策內容與生效日期尚未公告，請勿將本頁視為已生效的條款或服務承諾。</p>
  </div>;
}

export function PolicyDocument({ draft }: { draft: PolicyDraft }) {
  return (
    <PublicPolicyShell>
      <article className="mx-auto max-w-3xl">
        <div className="mb-6">
          <p className="text-sm font-semibold text-primary">政策與協助中心</p>
          <h1 className="mt-2 text-3xl font-bold tracking-tight text-slate-950">{publicPolicyTitle(draft)}</h1>
          <p className="mt-3 text-base leading-7 text-slate-600">查看正式政策的發布狀態、版本與生效日期。</p>
        </div>
        {/* D-5 has not supplied an approved version or effective date. Do not
            infer publication from a draft's internal status or owner fields. */}
        <UnpublishedPolicyNotice />
        <dl className="mt-4 grid gap-3 text-sm text-slate-700 sm:grid-cols-2" data-policy-publication="unpublished">
          <div><dt className="font-semibold">正式版本</dt><dd className="mt-1">尚未發布</dd></div>
          <div><dt className="font-semibold">生效日期</dt><dd className="mt-1">尚未公告</dd></div>
        </dl>
        {/* Unapproved working text stays in the internal draft registry. It is
            never published merely because a route or a status string exists. */}
        <section className="mt-8 rounded-lg border border-border bg-white p-6 shadow-sm" aria-labelledby="policy-help-title">
          <h2 id="policy-help-title" className="text-lg font-semibold text-slate-950">需要訂單協助？</h2>
          <p className="mt-3 text-sm leading-6 text-slate-600">你可以先查看訂單與履約進度，或查詢已有的客服案件。</p>
          <div className="mt-4 flex flex-wrap gap-4 text-sm">
            <Link className="min-h-11 inline-flex items-center font-semibold text-primary underline" href="/support/orders">查看訂單與履約進度</Link>
            <Link className="min-h-11 inline-flex items-center font-semibold text-primary underline" href="/support/requests">查詢客服案件</Link>
          </div>
        </section>
      </article>
    </PublicPolicyShell>
  );
}

import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { PolicyDocument, PublicPolicyShell, PublicResourceLinks } from "./public-policy";
import { policyDrafts, publicPolicyTitle } from "@/lib/public-policy-content";

describe("public policy and operations entrypoints", () => {
  it("exposes every public resource through accessible links", () => {
    const html = renderToStaticMarkup(<PublicPolicyShell><PublicResourceLinks /></PublicPolicyShell>);

    expect(html).toContain('aria-label="公開資訊"');
    expect(html).toContain('href="/policies/terms"');
    expect(html).toContain('href="/policies/privacy"');
    expect(html).toContain('href="/policies/refunds"');
    expect(html).toContain('href="/support"');
    expect(html).toContain('href="/merchant-onboarding"');
    expect(html).toContain('class="mt-4 text-center text-xs leading-5 text-slate-700"');
    expect(html).not.toContain('class="mt-4 text-center text-xs leading-5 text-slate-500"');
    expect(html).toContain("正式政策版本與生效日期會在發布後公告");
    expect(html).not.toContain("（草稿）");
  });

  it.each(Object.values(policyDrafts))("keeps the %s working text internal while showing its unpublished state", (draft) => {
    const html = renderToStaticMarkup(<PolicyDocument draft={draft} />);

    expect(html).toContain(publicPolicyTitle(draft));
    expect(html).not.toContain(draft.status);
    expect(html).toContain("政策尚未正式發布");
    expect(html).toContain('data-policy-publication="unpublished"');
    expect(html).toContain("正式版本");
    expect(html).toContain("尚未發布");
    expect(html).toContain("生效日期");
    expect(html).toContain("尚未公告");
    for (const section of draft.sections) {
      expect(section.paragraphs.length).toBeGreaterThan(0);
      expect(html).not.toContain(section.heading);
      for (const paragraph of section.paragraphs) expect(html).not.toContain(renderToStaticMarkup(<p>{paragraph}</p>));
    }
    expect(draft.sections.length).toBeGreaterThan(0);
    expect(html).toContain("正式政策內容與生效日期尚未公告");
    expect(html).toContain('href="/support/orders"');expect(html).toContain('href="/support/requests"');
    for(const internal of ["DRAFT","HUMAN OWNER","owner","P0","P1","P2","release sign-off"])expect(html).not.toContain(internal);
  });
  it("does not infer approval from internal draft metadata", () => {
    const html = renderToStaticMarkup(<PolicyDocument draft={{ ...policyDrafts.terms, status: "PUBLISHED 2026-01-01", owner: "approved-owner" }} />);
    expect(html).toContain("尚未發布");
    expect(html).toContain("尚未公告");
    expect(html).not.toContain("PUBLISHED 2026-01-01");
    expect(html).not.toContain("approved-owner");
    expect(html).not.toContain("<time");
  });
});

import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import SupportPage from "./page";

describe("/support route", () => {
  it("offers existing support paths without unconfirmed response promises", () => {
    const html = renderToStaticMarkup(<SupportPage />);

    expect(html).toContain("客服與付款協助");
    expect(html).toContain("客服聯絡管道與服務時段尚未公告");
    expect(html).toContain("目前無法承諾固定回應時間");
    expect(html).toContain("請勿提供完整卡號、卡片安全碼、帳號密碼、登入憑證或一次性驗證碼");
    expect(html).toContain('href="/support/orders"');
    expect(html).toContain('href="/policies/refunds"');
    expect(html).toContain('href="/merchant-onboarding"');
    expect(html).toContain('href="/support/requests"');
    for(const internal of ["DRAFT","HUMAN OWNER","P0","P1","P2","owner","webhook","目標 15 分鐘","目標 1 小時","目標 1 個工作日"])expect(html).not.toContain(internal);
  });
});
